package poller

import "time"

type Poller struct {
	Count int
	fetch func() error
}

func New(fetch func() error) *Poller {
	return &Poller{fetch: fetch}
}

func (p *Poller) Start() {
	go func() {
		for {
			if err := p.fetch(); err == nil {
				p.Count++
			}
			time.Sleep(time.Second)
		}
	}()
}

